/* Optional real HTTPS smoke test; no UI or hardware/audio assertions. */
#include "nxt_wallpapers.c"
#include <assert.h>
void NxtLog_step(const char*a,const char*b,bool ok,const char*c,...){}
static void finish(Gallery *g){for(int i=0;i<1200;i++){if(__atomic_load_n(&g->job.done,__ATOMIC_ACQUIRE)){pthread_join(g->job.thread,NULL);g->job.joined=0;assert(g->job.ok);return;}usleep(50000);}job_stop(g);assert(!"live request timed out");}
int main(int argc,char **argv){assert(argc==2);Gallery g={0};snprintf(g.cache,sizeof(g.cache),"%s",argv[1]);char path[512];snprintf(path,sizeof(path),"%s/live-catalog.json",argv[1]);assert(job_start(&g,JOB_CATALOG,NULL,"https://wallhaven.cc/api/v1/search?purity=100&categories=110&sorting=toplist&topRange=1M&q=landscape&page=1",path));finish(&g);FILE*f=fopen(path,"rb");assert(f);fseek(f,0,SEEK_END);long n=ftell(f);rewind(f);char*t=calloc(n+1,1);assert(t&&fread(t,1,n,f)==n);fclose(f);NxtWallpaperEntry items[24];int pages,count=NxtWallpaper_parseCatalog(t,items,24,&pages);free(t);assert(count>0&&pages>0);snprintf(path,sizeof(path),"%s/live-thumb.jpg",argv[1]);assert(job_start(&g,JOB_THUMB,&items[0],items[0].thumb,path));finish(&g);uint32_t x,y;assert(NxtWallpaper_imageSize(path,&x,&y));snprintf(path,sizeof(path),"%s/live-full.png",argv[1]);assert(job_start(&g,JOB_IMAGE,&items[0],items[0].url,path));finish(&g);assert(NxtWallpaper_imageSize(path,&x,&y)&&x<=1024&&y<=768);printf("PASS actual HTTPS/curl child, bundled CA, %d SFW records, thumbnail, full image and normalized PNG %ux%u; provider Wallhaven.\n",count,x,y);return 0;}
